/bin/bash -lc "python -c \"import urllib.request,re; t=urllib.request.urlopen('https://ccb.jhu.edu/openspliceai/content/pretrained_models/GRCh38_MANE.html').read().decode(); 
import re
for m in re.finditer(r'href=\\\"(["'^'"\\\"]+)\\\"["'^>]*>([''^<]*(?:Model [0-9]|OSAI[''^<]*))'"', t):
    print(m.group(2), m.group(1))
\""

/bin/bash -lc "python -c \"import urllib.request,re; t=urllib.request.urlopen('https://ccb.jhu.edu/openspliceai/content/pretrained_models/GRCh38_MANE.html').read().decode(); 
import re
for m in re.finditer(r'href=\\\"(["'^'"\\\"]+)\\\"["'^>]*>([''^<]*(?:Model [0-9]|OSAI[''^<]*))'"', t):
    print(m.group(2), m.group(1))
\""

/bin/bash -lc "python -c \"import urllib.request,re; t=urllib.request.urlopen('https://ccb.jhu.edu/openspliceai/content/pretrained_models/GRCh38_MANE.html').read().decode(); 
for m in re.finditer(r'<a["'^>]*href='"\\\"(["'^'"\\\"]+)\\\"["'^>]*>(.*?)</a>'"', t, flags=re.S):
    txt=re.sub(r'<["'^>]+>'"','',m.group(2)).strip()
    if 'Model' in txt or 'OSAI' in txt:
        print(repr(txt), m.group(1))
\""

/bin/bash -lc "python -c \"import urllib.request,re; t=urllib.request.urlopen('https://ccb.jhu.edu/openspliceai/content/pretrained_models/GRCh38_MANE.html').read().decode(); 
for m in re.finditer(r'<a["'^>]*href='"\\\"(["'^'"\\\"]+)\\\"["'^>]*>(.*?)</a>'"', t, flags=re.S):
    txt=re.sub(r'<["'^>]+>'"','',m.group(2)).strip()
    if 'Model' in txt or 'OSAI' in txt:
        print(repr(txt), m.group(1))
\""

